// The policy parser against the reference CLI, and the parts of a parsed policy that printing does
// not show. Each `tests/parity/policies/<name>.cedar` has a `<name>.expected` generated by
// scripts/generate-policy-parity-cases.sh: whether `cedar check-parse --policies` accepts the file
// and, when it does, Rust's canonical printing of the policy set.

#include "syntax/Printer.hpp"

#include <cedar/Expression.hpp>
#include <cedar/Policy.hpp>
#include <cedar/PolicySet.hpp>
#include <cedar/Syntax.hpp>

#include <gtest/gtest.h>

#include <algorithm>
#include <cstddef>
#include <filesystem>
#include <fstream>
#include <iterator>
#include <string>
#include <string_view>
#include <variant>
#include <vector>

namespace
{

auto ReadFile(const std::filesystem::path& path) -> std::string
{
    std::ifstream input{path, std::ios::binary};
    return {std::istreambuf_iterator<char>{input}, std::istreambuf_iterator<char>{}};
}

TEST(PolicyParser, AgreesWithTheReferenceCases)
{
    std::vector<std::filesystem::path> cases;
    for (const auto& entry : std::filesystem::directory_iterator{CEDAR_POLICY_PARITY_DIRECTORY})
    {
        if (entry.path().extension() == ".cedar") { cases.push_back(entry.path()); }
    }
    std::ranges::sort(cases);
    ASSERT_GE(cases.size(), 40U);
    for (const std::filesystem::path& path : cases)
    {
        SCOPED_TRACE(path.filename().string());
        std::filesystem::path expectedPath = path;
        expectedPath.replace_extension(".expected");
        const std::string expected = ReadFile(expectedPath);
        ASSERT_FALSE(expected.empty()) << "no expectation; run scripts/generate-policy-parity-cases.sh";

        const auto parsed = cedar::ParsePolicySet(ReadFile(path), path.filename().string());
        if (expected == "reject\n")
        {
            EXPECT_FALSE(parsed.has_value()) << "accepted:\n" << cedar::ToCedar(*parsed);
            continue;
        }
        ASSERT_TRUE(expected.starts_with("accept\n"));
        if (!parsed)
        {
            ADD_FAILURE() << "rejected:\n" << parsed.error().Render();
            continue;
        }
        // The CLI's `println!` ends the reference text with a line feed.
        EXPECT_EQ("accept\n" + cedar::detail::PrintPolicySet(*parsed, cedar::detail::TextChoice::Canonical) + "\n",
                  expected);
        // The retained text reads back as a policy set too.
        EXPECT_TRUE(cedar::ParsePolicySet(cedar::ToCedar(*parsed)).has_value());
    }
}

TEST(PolicyParser, ReportsAnErrorForEachBrokenPolicy)
{
    const auto parsed = cedar::ParsePolicySet("permit(principal action, resource);\n"
                                              "permit(principal, action, resource) when { 1 + };\n"
                                              "permit(principal, action, resource);\n"
                                              "forbid(principal, , resource);\n");
    ASSERT_FALSE(parsed.has_value());
    EXPECT_EQ(parsed.error().Diagnostics().size(), 3U) << parsed.error().Render();
}

TEST(PolicyParser, ReportsEveryConversionError)
{
    const auto parsed = cedar::ParsePolicySet("permit(principal, action == User::\"x\", resource);\n"
                                              "@a @a permit(principal, action, resource) when { foo };\n");
    ASSERT_FALSE(parsed.has_value());
    const auto& error = parsed.error();
    EXPECT_TRUE(error.HasCode(cedar::DiagnosticCode::InvalidActionType));
    EXPECT_TRUE(error.HasCode(cedar::DiagnosticCode::DuplicateAnnotation));
    EXPECT_TRUE(error.HasCode(cedar::DiagnosticCode::ArbitraryVariable));
}

TEST(PolicyParser, NamesPoliciesAndTemplatesByPosition)
{
    const auto parsed = cedar::ParsePolicySet("@id(\"first\") permit(principal, action, resource);\n"
                                              "permit(principal == ?principal, action, resource);\n"
                                              "forbid(principal, action, resource);\n");
    ASSERT_TRUE(parsed.has_value()) << parsed.error().Render();
    ASSERT_NE(parsed->GetPolicy("policy0"), nullptr); // `@id` does not name the policy.
    EXPECT_NE(parsed->GetTemplate("policy1"), nullptr);
    EXPECT_NE(parsed->GetPolicy("policy2"), nullptr);
    EXPECT_EQ(parsed->Policies().size(), 2U);
    EXPECT_EQ(parsed->Templates().size(), 1U);
}

TEST(PolicyParser, KeepsEachPolicyTextFromItsFirstToken)
{
    const std::string_view text = "// header\n  @a(\"x\")\npermit(principal, action, resource)\n"
                                  "  when { \"a;b\" == \"a;b\" } ;  // tail\nforbid ( principal , action , resource ) ;\n";
    const auto parsed = cedar::ParsePolicySet(text);
    ASSERT_TRUE(parsed.has_value()) << parsed.error().Render();
    const cedar::Policy* first = parsed->GetPolicy("policy0");
    const cedar::Policy* second = parsed->GetPolicy("policy1");
    ASSERT_NE(first, nullptr);
    ASSERT_NE(second, nullptr);
    EXPECT_EQ(cedar::ToCedar(*first), "@a(\"x\")\npermit(principal, action, resource)\n  when { \"a;b\" == \"a;b\" } ;");
    EXPECT_EQ(cedar::ToCedar(*second), "forbid ( principal , action , resource ) ;");
    EXPECT_EQ(cedar::ToCedar(*parsed), "@a(\"x\")\npermit(principal, action, resource)\n  when { \"a;b\" == \"a;b\" } ;"
                                       "\n\nforbid ( principal , action , resource ) ;");
}

TEST(PolicyParser, ParsePolicyTakesOneStaticPolicy)
{
    const std::string_view text = "  // note\npermit(principal, action, resource);\n";
    const auto policy = cedar::ParsePolicy(text);
    ASSERT_TRUE(policy.has_value()) << policy.error().Render();
    EXPECT_EQ(policy->Id(), "policy0");
    // Rust's `Policy::parse` keeps the whole text it was given.
    EXPECT_EQ(cedar::ToCedar(*policy), text);

    const auto named = cedar::ParsePolicy("forbid(principal, action, resource);", cedar::PolicyId{"mine"});
    ASSERT_TRUE(named.has_value());
    EXPECT_EQ(named->Id(), "mine");

    const auto slotted = cedar::ParsePolicy("permit(principal == ?principal, action, resource);");
    ASSERT_FALSE(slotted.has_value());
    EXPECT_TRUE(slotted.error().HasCode(cedar::DiagnosticCode::ExpectedStaticPolicy));

    EXPECT_FALSE(cedar::ParsePolicy("permit(principal, action, resource); permit(principal, action, resource);"));
    EXPECT_FALSE(cedar::ParsePolicy(""));
}

TEST(PolicyParser, ParseTemplateTakesOneTemplate)
{
    const auto body = cedar::ParseTemplate("permit(principal in ?principal, action, resource == ?resource);");
    ASSERT_TRUE(body.has_value()) << body.error().Render();
    EXPECT_EQ((*body)->Id(), "policy0");
    EXPECT_EQ((*body)->Slots().size(), 2U);
    const auto& principal = std::get<cedar::ScopeIn>((*body)->Principal().constraint);
    EXPECT_TRUE(std::holds_alternative<cedar::SlotReference>(principal.target));

    const auto staticBody = cedar::ParseTemplate("permit(principal, action, resource);");
    ASSERT_FALSE(staticBody.has_value());
    EXPECT_TRUE(staticBody.error().HasCode(cedar::DiagnosticCode::ExpectedTemplate));

    const auto conditionSlot =
        cedar::ParseTemplate("permit(principal == ?principal, action, resource) when { resource == ?resource };");
    ASSERT_FALSE(conditionSlot.has_value());
    EXPECT_TRUE(conditionSlot.error().HasCode(cedar::DiagnosticCode::SlotsInConditionClause));
}

TEST(PolicyParser, RecordsHowTheActionListWasWritten)
{
    const auto single = cedar::ParsePolicy("permit(principal, action in Action::\"a\", resource);");
    const auto list = cedar::ParsePolicy("permit(principal, action in [Action::\"a\"], resource);");
    ASSERT_TRUE(single.has_value());
    ASSERT_TRUE(list.has_value());
    EXPECT_FALSE(std::get<cedar::ActionIn>(single->GetTemplate().Action()).writtenAsList);
    EXPECT_TRUE(std::get<cedar::ActionIn>(list->GetTemplate().Action()).writtenAsList);
}

TEST(PolicyParser, CombinesConditionsAsARightFold)
{
    const auto policy = cedar::ParsePolicy(
        "permit(principal, action, resource) when { context.a } unless { context.b } when { context.c };");
    ASSERT_TRUE(policy.has_value()) << policy.error().Render();
    const cedar::Template& body = policy->GetTemplate();
    ASSERT_TRUE(body.NonScopeCondition().has_value());
    EXPECT_EQ(cedar::DumpExpression(body.Arena(), *body.NonScopeCondition()),
              "(&& (. context \"a\") (&& (! (. context \"b\")) (. context \"c\")))");
}

TEST(PolicyParser, KeepsAnnotations)
{
    const auto policy =
        cedar::ParsePolicy("@b(\"2\") @a @if(\"\\u{e9}\") permit(principal, action, resource);");
    ASSERT_TRUE(policy.has_value()) << policy.error().Render();
    const cedar::Annotations& annotations = policy->GetTemplate().GetAnnotations();
    ASSERT_EQ(annotations.Size(), 3U);
    EXPECT_EQ(annotations.Entries()[0].key.Text(), "a");
    EXPECT_FALSE(annotations.Entries()[0].value.has_value());
    EXPECT_EQ(annotations.Find("if"), "\xc3\xa9");
    EXPECT_EQ(annotations.Find("b"), "2");
}

} // namespace
